      const hnaNew = labels.slice(2).reduce((sum, label) => sum.map((value, index) => value + totals[label][index]), Array(12).fill(0));
      return { year: sourceYear, ...metricTotals, hnaExisting, hnaNew, hnaTotal: hnaExisting.map((value, index) => value + hnaNew[index]) };
